Câu 1 (1.5 điểm)1. Phân tích số phép toán cơ bản nhiều nhất (Trường hợp xấu nhất)Trường hợp xấu nhất xảy ra khi tất cả các phần tử trong mảng $a[1..n]$ đều khác nhau từng đôi một.Lần lặp $i = 2$: $k = 0 \to 1$, vòng lặp $j$ thực hiện $0$ lần.Lần lặp $i = 3$: $k = 1$, vòng lặp $j$ chạy $1$ lần (kiểm tra $a[1] == a[3]$), sau đó chèn thêm vào $a$ làm $k = 2$.Lần lặp $i = 4$: $k = 2$, vòng lặp $j$ chạy $2$ lần....Lần lặp $i$: vòng lặp $j$ thực hiện $(i - 2)$ so sánh.Tổng số lần thực hiện các phép toán cơ bản (so sánh, gán) ở vòng lặp trong cùng là:$$S = \sum_{i=2}^{n} (i - 2) = 0 + 1 + 2 + \dots + (n - 2) = \frac{(n - 2)(n - 1)}{2}$$Số phép toán cơ bản nhiều nhất là $\frac{n^2 - 3n + 2}{2}$ phép toán.2. Độ phức tạp của thuật toánĐộ phức tạp thời gian (Time Complexity): $O(n^2)$Độ phức tạp không gian (Space Complexity): $O(1)$ (biến đổi trực tiếp trên mảng đã có).Câu 2: Tìm kiếm nhị phân (Cây tìm kiếm nhị phân)1. Khái niệm & Cấu trúc lớpKhái niệm: Cây tìm kiếm nhị phân (BST) là cây nhị phân thỏa mãn: nút cha có khóa lớn hơn tất cả các khóa ở cây con trái và nhỏ hơn tất cả các khóa ở cây con phải. Các cây con trái và phải cũng là cây tìm kiếm nhị phân.Cấu trúc lớp của cây tìm kiếm nhị phân:C++template 
class BSTree {
private:
    Node* rootNode;

public:
    BSTree() : rootNode(nullptr) {}

    // Thuộc tính & Phương thức truy cập
    Node* root() { return rootNode; }

    int size();
    int isEmpty();
    int isInternal(Node* p);
    int isExternal(Node* p);
    int isRoot(Node* p);

    // Duyệt cây
    void preOrder(Node* p);
    void inOrder(Node* p);
    void postOrder(Node* p);

    // Thao tác chính
    Node* search(Keys k, Node* p);
    Node* insert(Keys k, T val);
    void remove(Keys k);
};
2. Cài đặt các phương thức theo yêu cầuGiả sử cấu trúc Node mẫu như đề bài cung cấp:C++template 
struct Node {
    T elem;
    Node* left;
    Node* right;
    Node(T val) : elem(val), left(nullptr), right(nullptr) {}
};
a) Hàm T max(T x) (Tìm phần tử lớn nhất)Phần tử lớn nhất trong BST nằm ở nút xa nhất bên phải.C++template 
T max(Node* root) {
    // Giả thiết cây đã khác rỗng (root != nullptr)
    Node* current = root;
    while (current->right != nullptr) {
        current = current->right;
    }
    return current->elem;
}
b) Hàm void erase(T x) (Xóa phần tử $x$ khỏi cây)C++template 
Node* removeNode(Node* root, T x) {
    if (root == nullptr) return nullptr;

    if (x < root->elem) {
        root->left = removeNode(root->left, x);
    } else if (x > root->elem) {
        root->right = removeNode(root->right, x);
    } else {
        // Trường hợp 1 & 2: Nút có 0 hoặc 1 con
        if (root->left == nullptr) {
            Node* temp = root->right;
            delete root;
            return temp;
        } else if (root->right == nullptr) {
            Node* temp = root->left;
            delete root;
            return temp;
        }
        // Trường hợp 3: Nút có 2 con -> Tìm nút nhỏ nhất bên cây con phải
        Node* temp = root->right;
        while (temp && temp->left != nullptr) {
            temp = temp->left;
        }
        root->elem = temp->elem;
        root->right = removeNode(root->right, temp->elem);
    }
    return root;
}

template 
void erase(Node*& root, T x) {
    root = removeNode(root, x);
}
