using namespace std;

// Class biểu diễn Laptop
class Laptop {
private:
    string maMay;
    string hangSX;
    string tenMay;
    string cauHinh;
    double donGia;
    int soLuong;

public:
    Laptop() : donGia(0), soLuong(0) {}
    Laptop(string ma, string hang, string ten, string ch, double gia, int sl)
        : maMay(ma), hangSX(hang), tenMay(ten), cauHinh(ch), donGia(gia), soLuong(sl) {}

    string getMaMay() const { return maMay; }
    string getHangSX() const { return hangSX; }
    double getDonGia() const { return donGia; }
    int getSoLuong() const { return soLuong; }

    friend istream& operator>>(istream& is, Laptop& l) {
        cout << "Nhap ma may: "; is >> l.maMay;
        cout << "Nhap hang SX: "; is >> l.hangSX;
        is.ignore();
        cout << "Nhap ten may: "; getline(is, l.tenMay);
        cout << "Nhap cau hinh: "; getline(is, l.cauHinh);
        cout << "Nhap don gia: "; is >> l.donGia;
        cout << "Nhap so luong: "; is >> l.soLuong;
        return is;
    }

    friend ostream& operator<<(ostream& os, const Laptop& l) {
        os << "Ma: " << l.maMay << " | Hang: " << l.hangSX 
           << " | Ten: " << l.tenMay << " | Cau hinh: " << l.cauHinh 
           << " | Don gia: " << l.donGia << " | So luong: " << l.soLuong;
        return os;
    }
};

// Class quản lý danh sách Laptop
class QuanLyLaptop {
private:
    vector dsLaptop;

public:
    void themLaptop(const Laptop& l) {
        dsLaptop.push_back(l);
    }

    double tinhTongGiaTriTheoHang(const string& hang) const {
        double tong = 0;
        for (const auto& l : dsLaptop) {
            if (l.getHangSX() == hang) {
                tong += l.getDonGia() * l.getSoLuong();
            }
        }
        return tong;
    }

    void inDanhSach() const {
        for (const auto& l : dsLaptop) {
            cout << l << endl;
        }
    }

    // Tim kiem nhi phan theo ma (danh sach da duoc sap xep tang dan theo maMay)
    int timKiemBinary(const string& ma) const {
        int left = 0;
        int right = dsLaptop.size() - 1;
        while (left <= right) {
            int mid = left + (right - left) / 2;
            if (dsLaptop[mid].getMaMay() == ma) {
                return mid; // Tra ve vi tri tim thay
            }
            if (dsLaptop[mid].getMaMay() < ma) {
                left = mid + 1;
            } else {
                right = mid - 1;
            }
        }
        return -1; // Khong tim thay
    }
};
Câu 4: Merge Sort (Sắp xếp trộn)1. Tư tưởng thuật toánThuật toán Merge Sort áp dụng chiến lược Chia để trị (Divide and Conquer):Chia (Divide): Chia mảng cần sắp xếp có $N$ phần tử thành 2 mảng con có kích thước tương đương nhau ($N/2$).Trị (Conquer): Đệ quy sắp xếp từng mảng con. Trường hợp cơ sở: Mảng con chỉ chứa 1 phần tử (đã tự sắp xếp).Trộn (Combine): Trộn (Merge) hai mảng con đã được sắp xếp thành một mảng lớn hoàn chỉnh duy nhất đã được sắp xếp.2. Mã giả (Pseudocode)PlaintextAlgorithm MergeSort(A, left, right):
    if left < right then
        mid = left + (right - left) / 2

        // 1 & 2. Chia nhỏ và đệ quy
        MergeSort(A, left, mid)
        MergeSort(A, mid + 1, right)

        // 3. Trộn hai mảng con đã sắp xếp
        Merge(A, left, mid, right)

Algorithm Merge(A, left, mid, right):
    n1 = mid - left + 1
    n2 = right - mid

    Tạo hai mảng tạm L[1..n1] và R[1..n2]
    Copy dữ liệu từ A[left..mid] vào L
    Copy dữ liệu từ A[mid+1..right] vào R

    i = 1, j = 1, k = left
    while i <= n1 và j <= n2 do
        if L[i] <= R[j] then
            A[k] = L[i]
            i = i + 1
        else
            A[k] = R[j]
            j = j + 1
        k = k + 1

    // Chép các phần tử còn lại nếu có
    while i <= n1 do
        A[k] = L[i], i = i + 1, k = k + 1
    while j <= n2 do
        A[k] = R[j], j = j + 1, k = k + 1
